'use strict';

// MODULES //

var isInteger = require( '@stdlib/math/base/assert/is-integer' );
var isObject = require( '@stdlib/assert/is-object' );
var Complex128 = require( '@stdlib/complex/float64/ctor' );
var slice = require( '@stdlib/array/slice' );
var join = require( '@stdlib/array/base/join' );
var containsString = require( '@stdlib/assert/contains' );
var round = require( '@stdlib/math/base/special/round' );


// FUNCTIONS //

/**
* Returns a string containing example values for a 2x2 array environment variable.
*
* @private
* @param {Array} values - example values
* @returns {string} environment variable string
*
* @example
* var exampleValues = [ 1.9, 4.8, 6.0, 8.1 ];
*
* var out = jsExampleValues2x2EnvVar( exampleValues );
* // returns "JS_EXAMPLE_VALUES_2X2='[ [ 1.9, 4.8 ], [ 6, 8.1 ] ]'"
*
* @example
* var exampleValues = [
*     {
*         "re": 0,
*         "im": 0
*     },
*     {
*         "re": 1,
*         "im": 0
*     },
*     {
*         "re": -3.14,
*         "im": -1.5
*     },
*     {
*         "re": -1.5,
*         "im": 2.5
*     }
* ];
*
* var out = jsExampleValues2x2EnvVar( exampleValues );
* // returns "JS_EXAMPLE_VALUES_2X2='[ 0, 0, 1, 0, -3.14, -1.5, -1.5, 2.5 ]'"
*/
function jsExampleValues2x2EnvVar( values ) {
	var bottomRow;
	var topRow;
	var vals;
	var v;
	var i;

	vals = [];

	// Case: Complex values...
	if ( isObject( values[ 0 ] ) ) {
		for ( i = 0; i < 4; i++ ) {
			v = values[ i ];
			vals.push( v.re.toString() );
			vals.push( v.im.toString() );
		}
		return 'JS_EXAMPLE_VALUES_2X2=\'[ ' + join( vals, ', ' ) + ' ]\'';
	}

	// Case: Real values...
	for ( i = 0; i < 4; i++ ) {
		v = values[ i ];
		vals.push( v.toString() );
	}
	topRow = join( slice( vals, 0, 2 ), ', ' );
	bottomRow = join( slice( vals, 2, 4 ), ', ' );
	return 'JS_EXAMPLE_VALUES_2X2=\'[ [ ' + topRow + ' ], [ ' + bottomRow + ' ] ]\'';
}

/**
* Formats a floating-point result value as a string.
*
* @private
* @param {number} value - result value
* @param {string} outputDtypes - output dtype policy
* @returns {string} formatted string
*
* @example
* var out = formatResultValue( 1.0, 'integer' );
* // returns '1'
*
* @example
* var out = formatResultValue( 0.5403023058681398, 'real_and_generic' );
* // returns '~0.54'
*/
function formatResultValue( value, outputDtypes ) {
	var isFloatingPoint;
	var rounded;
	var str;

	isFloatingPoint = containsString( outputDtypes, 'floating_point' ) ||
		containsString( outputDtypes, 'real_and_generic' ) ||
		containsString( outputDtypes, 'complex' );

	rounded = round( value * 100 ) / 100;
	str = rounded.toString();

	if ( isInteger( rounded ) ) {
		if ( isFloatingPoint && !containsString( str, '.' ) ) {
			str += '.0';
		}
	} else {
		str = '~' + str;
	}
	return str;
}

/**
* Formats a complex result value as a string.
*
* @private
* @param {number} re - real component
* @param {number} im - imaginary component
* @param {string} outputDtypes - output dtype policy
* @returns {string} formatted string
*
* @example
* var out = formatComplexResultValue( 1.0, 0.0, 'complex_floating_point_and_generic' );
* // returns 'Complex128 { re: 1.0, im: 0.0 }'
*
* @example
* var out = formatComplexResultValue( 0.5403, 0.8414, 'complex_floating_point_and_generic' );
* // returns 'Complex128 { re: ~0.54, im: ~0.84 }'
*/
function formatComplexResultValue( re, im, outputDtypes ) {
	var reStr = formatResultValue( re, outputDtypes );
	var imStr = formatResultValue( im, outputDtypes );
	return 'Complex128 { re: ' + reStr + ', im: ' + imStr + ' }';
}

/**
* Returns a string containing example results for a 2x2 array environment variable.
*
* @private
* @param {Array} values - input values
* @param {string} functionAlias - function alias
* @param {string} outputDtypes - output dtype policy
* @returns {string} environment variable string
*
* @example
* var exampleValues = [ 0.0, 1.57, 3.14, 4.71 ];
*
* var out = jsExampleResults2x2EnvVar( exampleValues, 'sin', 'real_and_generic' );
* // returns "JS_EXAMPLE_RESULTS_2X2='[ [ 0.0, 1.0 ], [ 0.0, -1.0 ] ]'"
*
* @example
* var exampleValues = [
*     {
*         "re": 0,
*         "im": 0
*     },
*     {
*         "re": 1,
*         "im": 0
*     },
*     {
*         "re": -3.14,
*         "im": -1.5
*     },
*     {
*         "re": -1.5,
*         "im": 2.5
*     }
* ];
*
* var out = jsExampleResults2x2EnvVar( exampleValues, 'ccis', 'complex_floating_point_and_generic' );
* // returns "JS_EXAMPLE_RESULTS_2X2='[ [ Complex128 { re: 1.0, im: 0.0 }, Complex128 { re: ~0.54, im: ~0.84 } ], [ Complex128 { re: ~-4.48, im: ~-0.01 }, Complex128 { re: ~0.01, im: ~-0.08 } ] ]'"
*/
function jsExampleResults2x2EnvVar( values, functionAlias, outputDtypes ) {
	var bottomRow;
	var results;
	var topRow;
	var func;
	var vals;
	var z;
	var v;
	var i;

	func = require( '@stdlib/math/base/special/' + functionAlias ); // eslint-disable-line stdlib/no-dynamic-require

	vals = [];

	// Case: Complex values...
	if ( isObject( values[ 0 ] ) ) {
		for ( i = 0; i < 4; i++ ) {
			v = values[ i ];
			z = new Complex128( v.re, v.im );
			results = func( z );
			vals.push( formatComplexResultValue( results.re, results.im, outputDtypes ) ); // eslint-disable-line max-len
		}
		topRow = vals[ 0 ] + ', ' + vals[ 1 ];
		bottomRow = vals[ 2 ] + ', ' + vals[ 3 ];
		return 'JS_EXAMPLE_RESULTS_2X2=\'[ [ ' + topRow + ' ], [ ' + bottomRow + ' ] ]\'';
	}

	// Case: Real values...
	for ( i = 0; i < 4; i++ ) {
		v = values[ i ];
		results = func( v );
		vals.push( formatResultValue( results, outputDtypes ) );
	}
	topRow = join( slice( vals, 0, 2 ), ', ' );
	bottomRow = join( slice( vals, 2, 4 ), ', ' );
	return 'JS_EXAMPLE_RESULTS_2X2=\'[ [ ' + topRow + ' ], [ ' + bottomRow + ' ] ]\'';
}


// EXPORTS //

module.exports = {
	'jsExampleValues2x2EnvVar': jsExampleValues2x2EnvVar,
	'jsExampleResults2x2EnvVar': jsExampleResults2x2EnvVar
};
